public class CSVParser_getHeaderMap_TriageGen0Test {

    @Test
    public void testGetHeaderMapWithValidCsv() throws IOException {
        String csvContent = "id,name,age\n1,John,30\n2,Jane,25";
        CSVFormat format = CSVFormat.DEFAULT.withFirstRecordAsHeader();

        try (CSVParser parser = CSVParser.parse(csvContent, format)) {
            Map<String, Integer> headerMap = parser.getHeaderMap();

            // Verify content and size
            assertEquals(3, headerMap.size());
            assertEquals(Integer.valueOf(0), headerMap.get("id"));
            assertEquals(Integer.valueOf(1), headerMap.get("name"));
            assertEquals(Integer.valueOf(2), headerMap.get("age"));

            // Verify that it returns a copy (defensive copy check)
            // The implementation uses new LinkedHashMap<>(this.headerMap)
            assertNotSame("The returned map should be a new instance (defensive copy)", 
                parser.getHeaderMap(), parser.getHeaderMap());
        }
    }

    @Test
    public void testGetHeaderMapWithNoHeader() throws IOException {
        String csvContent = "1,John,30\n2,Jane,25";
        CSVFormat format = CSVFormat.DEFAULT; // No header defined

        try (CSVParser parser = CSVParser.parse(csvContent, format)) {
            Map<String, Integer> headerMap = parser.getHeaderMap();

            assertTrue("Header map should be empty when no header is defined", headerMap.isEmpty());
        }
    }

    @Test
    public void testGetHeaderMapWithEmptyContent() throws IOException {
        String csvContent = "";
        CSVFormat format = CSVFormat.DEFAULT.withFirstRecordAsHeader();

        try (CSVParser parser = CSVParser.parse(csvContent, format)) {
            Map<String, Integer> headerMap = parser.getHeaderMap();
            assertTrue(headerMap.isEmpty());
        }
    }

    @Test
    public void testGetHeaderMapImmutabilityOfOriginal() throws IOException {
        String csvContent = "col1,col2";
        CSVFormat format = CSVFormat.DEFAULT.withFirstRecordAsHeader();

        try (CSVParser parser = CSVParser.parse(csvContent, format)) {
            Map<String, Integer> headerMap = parser.getHeaderMap();

            // Attempt to modify the returned map
            headerMap.put("newCol", 99);

            // The internal state of the parser should remain unchanged
            Map<String, Integer> secondCall = parser.getHeaderMap();
            assertEquals("The internal headerMap should not be affected by modifications to the returned map", 
                2, secondCall.size());
            assertTrue("The new column should not exist in the parser's internal map", 
                !secondCall.containsKey("newCol"));
        }
    }
}
